const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// Color palette: Midnight Executive (navy/ice blue/white) with a teal accent for tech feel
const C = {
  navy: "1E2761",
  ice: "CADCFC",
  white: "FFFFFF",
  teal: "0D9488",
  tealLight: "14B8A6",
  slate: "334155",
  muted: "64748B",
  lightBg: "F8FAFC",
  accentBg: "E0F2FE",
  reject: "B85042",
  accept: "2C5F2D",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems";
pres.author = "SkillClaw Research";
pres.subject = "Collective Skill Evolution for Multi-User LLM Agent Ecosystems";

// Helper to make fresh shadow objects (avoid reuse mutation)
function makeShadow(opts = {}) {
  return {
    type: "outer",
    color: "000000",
    blur: 6,
    offset: 2,
    angle: 135,
    opacity: 0.12,
    ...opts,
  };
}

// Slide 1: Title Slide
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Subtle accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems", {
    x: 0.7, y: 1.6, w: 8.6, h: 1.4,
    fontSize: 38, fontFace: "Calibri", bold: true, color: C.white,
    align: "left", valign: "top",
    margin: 0,
  });

  // Tagline
  slide.addText("Let Skills Evolve Collectively with an Agentic Evolver", {
    x: 0.7, y: 3.1, w: 8.6, h: 0.5,
    fontSize: 20, fontFace: "Calibri", color: C.ice,
    align: "left", valign: "middle",
    margin: 0,
  });

  // Source
  slide.addText("arXiv:2604.08377", {
    x: 0.7, y: 4.4, w: 8.6, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: C.ice,
    align: "left", valign: "middle",
    margin: 0,
  });

  // Architecture hero image on right side
  const figPath = "/app/benchmark/assets/figure_1.jpg";
  if (fs.existsSync(figPath)) {
    slide.addImage({
      path: figPath,
      x: 6.2, y: 1.3, w: 3.5, h: 2.8,
      sizing: { type: "contain", w: 3.5, h: 2.8 },
    });
  }
}

// Slide 2: Problem — Static Skills
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("Agent Skills Remain Static After Deployment — Users Rediscover Solutions Independently", {
    x: 0.5, y: 0.35, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "top",
    margin: 0,
  });

  // Two-column cards: Static vs Evolving
  const cardH = 3.2;
  const cardY = 1.5;
  const cardW = 4.4;

  // Left card: Static
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: cardY, w: cardW, h: cardH,
    fill: { color: C.white },
    line: { color: C.ice, width: 1 },
    shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: cardY, w: cardW, h: 0.45,
    fill: { color: C.reject },
  });
  slide.addText("Static Skill Paradigm", {
    x: 0.5, y: cardY, w: cardW, h: 0.45,
    fontSize: 16, fontFace: "Calibri", bold: true, color: C.white,
    align: "center", valign: "middle",
    margin: 0,
  });
  slide.addText([
    { text: "Skills manually installed from a centralized hub", options: { bullet: true, breakLine: true } },
    { text: "Solutions discovered during interaction rarely persist", options: { bullet: true, breakLine: true } },
    { text: "Same failure/recovery patterns repeated across users", options: { bullet: true, breakLine: true } },
    { text: "Memory-based methods tied to specific instances", options: { bullet: true, breakLine: true } },
    { text: "Skill libraries treated as static resources", options: { bullet: true } },
  ], {
    x: 0.7, y: cardY + 0.6, w: cardW - 0.4, h: cardH - 0.8,
    fontSize: 14, fontFace: "Calibri", color: C.slate,
    align: "left", valign: "top",
    paraSpaceAfter: 8,
  });

  // Right card: Evolving
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: cardY, w: cardW, h: cardH,
    fill: { color: C.white },
    line: { color: C.ice, width: 1 },
    shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: cardY, w: cardW, h: 0.45,
    fill: { color: C.accept },
  });
  slide.addText("Evolving Skill Paradigm", {
    x: 5.1, y: cardY, w: cardW, h: 0.45,
    fontSize: 16, fontFace: "Calibri", bold: true, color: C.white,
    align: "center", valign: "middle",
    margin: 0,
  });
  slide.addText([
    { text: "Skills improve continuously from runtime experience", options: { bullet: true, breakLine: true } },
    { text: "Cross-user trajectories aggregated into shared evidence", options: { bullet: true, breakLine: true } },
    { text: "System-level knowledge accumulation over time", options: { bullet: true, breakLine: true } },
    { text: "Agentic reasoning drives open-ended skill mutations", options: { bullet: true, breakLine: true } },
    { text: "Verified updates synchronized to all agents", options: { bullet: true } },
  ], {
    x: 5.3, y: cardY + 0.6, w: cardW - 0.4, h: cardH - 0.8,
    fontSize: 14, fontFace: "Calibri", color: C.slate,
    align: "left", valign: "top",
    paraSpaceAfter: 8,
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.9, w: 9, h: 0.55,
    fill: { color: C.navy },
  });
  slide.addText("Key Insight: Each user is forced to rediscover solutions independently, preventing knowledge from accumulating at the system level.", {
    x: 0.7, y: 4.9, w: 8.6, h: 0.55,
    fontSize: 14, fontFace: "Calibri", italic: true, color: C.ice,
    align: "left", valign: "middle",
    margin: 0,
  });
}

// Slide 3: Architecture Overview (closed-loop diagram)
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "top",
    margin: 0,
  });

  // Architecture image
  const figPath = "/app/benchmark/assets/figure_1.jpg";
  if (fs.existsSync(figPath)) {
    slide.addImage({
      path: figPath,
      x: 0.5, y: 1.1, w: 5.8, h: 2.7,
      sizing: { type: "contain", w: 5.8, h: 2.7 },
    });
  }

  // Four-stage box on the right
  const stages = [
    { label: "Evidence", desc: "Analyze trajectories to identify behavioral patterns", color: "0D9488" },
    { label: "Attribution", desc: "Diagnose root causes of failures and successes", color: "1C7293" },
    { label: "Evolution", desc: "Propose skill mutations — refine or create new skills", color: "1E2761" },
    { label: "Distribution", desc: "Verify, merge into shared repo, and sync to all agents", color: "21295C" },
  ];

  const boxX = 6.5;
  const boxW = 3.0;
  const startY = 1.15;
  const boxH = 0.62;
  const gap = 0.18;

  stages.forEach((s, i) => {
    const y = startY + i * (boxH + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: boxX, y: y, w: boxW, h: boxH,
      fill: { color: s.color },
      shadow: makeShadow(),
    });
    slide.addText(s.label, {
      x: boxX + 0.1, y: y, w: boxW - 0.2, h: 0.3,
      fontSize: 14, fontFace: "Calibri", bold: true, color: C.white,
      align: "left", valign: "middle",
      margin: 0,
    });
    slide.addText(s.desc, {
      x: boxX + 0.1, y: y + 0.28, w: boxW - 0.2, h: 0.3,
      fontSize: 11, fontFace: "Calibri", color: C.ice,
      align: "left", valign: "middle",
      margin: 0,
    });
  });

  // Bottom summary
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.05, w: 9, h: 1.35,
    fill: { color: C.white },
    line: { color: C.ice, width: 1 },
    shadow: makeShadow(),
  });
  slide.addText("Multi-user Interaction  →  Session Collection  →  Skill Evolution  →  Skill Synchronization", {
    x: 0.7, y: 4.15, w: 8.6, h: 0.4,
    fontSize: 16, fontFace: "Calibri", bold: true, color: C.navy,
    align: "center", valign: "middle",
    margin: 0,
  });
  slide.addText("Independent agents produce structured session trajectories preserving full action–feedback causal chains. Trajectories are aggregated across users, grouped by referenced skills, and fed into an autonomous agentic evolver performing open-ended reasoning over interaction evidence.", {
    x: 0.7, y: 4.55, w: 8.6, h: 0.75,
    fontSize: 12, fontFace: "Calibri", color: C.slate,
    align: "left", valign: "top",
    margin: 0,
  });
}

// Slide 4: Agentic Evolver Pipeline
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("Agentic Evolver: Evidence → Attribution → Evolution in Three Stages", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "top",
    margin: 0,
  });

  // Three large stage cards across the slide
  const cardW = 2.9;
  const cardH = 3.0;
  const cardY = 1.3;
  const stages = [
    {
      num: "01",
      title: "Evidence",
      body: "Analyze the aggregated trajectories to identify behavioral patterns. The evolver examines action–feedback causal chains across diverse user contexts to surface recurring success signals and failure modes.",
      color: "0D9488",
    },
    {
      num: "02",
      title: "Attribution",
      body: "Diagnose root causes of failures and successes. By cross-referencing complementary views from different users, the evolver separates generalizable conditions from idiosyncratic fixes.",
      color: "1C7293",
    },
    {
      num: "03",
      title: "Evolution",
      body: "Propose skill mutations — refining existing skills or creating new ones. Updates are produced through open-ended agent reasoning, not predefined update rules, enabling context-aware adaptation.",
      color: "1E2761",
    },
  ];

  stages.forEach((s, i) => {
    const x = 0.5 + i * (cardW + 0.15);
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.white },
      line: { color: C.ice, width: 1 },
      shadow: makeShadow(),
    });
    // Top colored band
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: 0.55,
      fill: { color: s.color },
    });
    slide.addText(s.num, {
      x: x + 0.12, y: cardY, w: 0.6, h: 0.55,
      fontSize: 22, fontFace: "Calibri", bold: true, color: C.white,
      align: "left", valign: "middle",
      margin: 0,
    });
    slide.addText(s.title, {
      x: x + 0.7, y: cardY, w: cardW - 0.85, h: 0.55,
      fontSize: 18, fontFace: "Calibri", bold: true, color: C.white,
      align: "left", valign: "middle",
      margin: 0,
    });
    slide.addText(s.body, {
      x: x + 0.12, y: cardY + 0.7, w: cardW - 0.24, h: cardH - 0.9,
      fontSize: 13, fontFace: "Calibri", color: C.slate,
      align: "left", valign: "top",
      margin: 0,
    });
  });

  // Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.5, w: 9, h: 0.7,
    fill: { color: C.navy },
  });
  slide.addText("The evolution process is driven by an autonomous agent performing open-ended reasoning over interaction evidence, not predefined update rules.", {
    x: 0.7, y: 4.5, w: 8.6, h: 0.7,
    fontSize: 14, fontFace: "Calibri", italic: true, color: C.ice,
    align: "left", valign: "middle",
    margin: 0,
  });
}

// Slide 5: Cross-User Trajectory Aggregation
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("Cross-User Trajectory Aggregation Exposes Skill Behavioral Boundaries", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "top",
    margin: 0,
  });

  // Left: key insight card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 4.4, h: 3.6,
    fill: { color: C.white },
    line: { color: C.ice, width: 1 },
    shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 0.08, h: 3.6,
    fill: { color: C.teal },
  });
  slide.addText("Why Cross-User Aggregation Matters", {
    x: 0.75, y: 1.45, w: 3.9, h: 0.4,
    fontSize: 18, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText([
    { text: "Different users exercising the same skill under diverse contexts produce complementary views of that skill's behavioral boundary.", options: { breakLine: true } },
    { text: "", options: { breakLine: true } },
    { text: "Reveals both conditions under which the skill works and those under which it breaks.", options: { breakLine: true } },
    { text: "", options: { breakLine: true } },
    { text: "A single user rarely generates enough signal to separate a generalizable improvement from an idiosyncratic fix.", options: { breakLine: true } },
  ], {
    x: 0.75, y: 1.95, w: 3.9, h: 2.7,
    fontSize: 14, fontFace: "Calibri", color: C.slate,
    align: "left", valign: "top",
    paraSpaceAfter: 6,
    margin: 0,
  });

  // Right: compatible systems + visual metaphor
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 1.3, w: 4.4, h: 3.6,
    fill: { color: C.white },
    line: { color: C.ice, width: 1 },
    shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 1.3, w: 4.4, h: 0.45,
    fill: { color: C.navy },
  });
  slide.addText("Compatible Claw-Style Systems", {
    x: 5.1, y: 1.3, w: 4.4, h: 0.45,
    fontSize: 16, fontFace: "Calibri", bold: true, color: C.white,
    align: "center", valign: "middle",
    margin: 0,
  });

  const systems = [
    "OpenClaw", "CoPaw", "IronClaw", "PicoClaw",
    "ZeroClaw", "NanoClaw", "NemoClaw",
  ];
  const sysStartY = 1.95;
  systems.forEach((sys, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const sx = 5.3 + col * 2.0;
    const sy = sysStartY + row * 0.48;
    // small circle + text
    slide.addShape(pres.shapes.OVAL, {
      x: sx, y: sy, w: 0.22, h: 0.22,
      fill: { color: C.teal },
    });
    slide.addText(sys, {
      x: sx + 0.3, y: sy - 0.02, w: 1.7, h: 0.28,
      fontSize: 13, fontFace: "Calibri", color: C.slate,
      align: "left", valign: "middle",
      margin: 0,
    });
  });

  // Bottom stat callout inside right card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 4.0, w: 4.0, h: 0.7,
    fill: { color: C.accentBg },
  });
  slide.addText("Evaluation on WildClawBench (Qwen3-Max backbone) demonstrates substantial improvements across tasks.", {
    x: 5.45, y: 4.0, w: 3.7, h: 0.7,
    fontSize: 12, fontFace: "Calibri", italic: true, color: C.navy,
    align: "left", valign: "middle",
    margin: 0,
  });
}

// Slide 6: Case Study — Creative Pipeline
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("Case Study: Multimodal Creative Pipeline Skill — 6 Days of Evolution Attempts", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "top",
    margin: 0,
  });

  // Table
  const tableData = [
    [
      { text: "Day", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Candidate Skill", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Validator", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Next-Day Action", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
    ],
    [
      { text: "1", options: { align: "center" } },
      { text: "validate-tmp-workspace-inputs", options: { align: "left" } },
      { text: "Accept", options: { fill: { color: "D1FAE5" }, color: C.accept, bold: true, align: "center" } },
      { text: "Upgrade to new best pool", options: { align: "left" } },
    ],
    [
      { text: "2", options: { align: "center" } },
      { text: "multimodal-input-validation-and-setup", options: { align: "left" } },
      { text: "Reject", options: { fill: { color: "FEE2E2" }, color: C.reject, bold: true, align: "center" } },
      { text: "Keep current best pool", options: { align: "left" } },
    ],
    [
      { text: "3", options: { align: "center" } },
      { text: "multimodal-creative-task-pipeline", options: { align: "left" } },
      { text: "Reject", options: { fill: { color: "FEE2E2" }, color: C.reject, bold: true, align: "center" } },
      { text: "Keep current best pool", options: { align: "left" } },
    ],
    [
      { text: "4", options: { align: "center" } },
      { text: "multimodal-creative-task-pipeline (impr.)", options: { align: "left" } },
      { text: "Reject", options: { fill: { color: "FEE2E2" }, color: C.reject, bold: true, align: "center" } },
      { text: "Keep current best pool", options: { align: "left" } },
    ],
    [
      { text: "5", options: { align: "center" } },
      { text: "creative pipeline + per-file fail-fast validation", options: { align: "left" } },
      { text: "Reject", options: { fill: { color: "FEE2E2" }, color: C.reject, bold: true, align: "center" } },
      { text: "Keep current best pool", options: { align: "left" } },
    ],
    [
      { text: "6", options: { align: "center" } },
      { text: "extended PDF-to-poster / document-to-visual paths", options: { align: "left" } },
      { text: "Reject", options: { fill: { color: "FEE2E2" }, color: C.reject, bold: true, align: "center" } },
      { text: "Not admitted to next cycle", options: { align: "left" } },
    ],
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.2, w: 9, h: 3.2,
    fontSize: 12, fontFace: "Calibri", color: C.slate,
    border: { pt: 0.5, color: "CBD5E1" },
    colW: [0.8, 3.8, 1.4, 3.0],
    rowH: [0.45, 0.45, 0.45, 0.45, 0.45, 0.45, 0.45],
    valign: "middle",
  });

  // Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.6, w: 9, h: 0.65,
    fill: { color: C.navy },
  });
  slide.addText("Only 1 of 6 candidates was accepted, illustrating the conservative verification process that prevents regressions.", {
    x: 0.7, y: 4.6, w: 8.6, h: 0.65,
    fontSize: 14, fontFace: "Calibri", italic: true, color: C.ice,
    align: "left", valign: "middle",
    margin: 0,
  });
}

// Slide 7: Case Study — Git Push Auth-Fallback
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("Case Study: Git Push Auth-Fallback Skill — Iterative Refinement Over 6 Days", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 26, fontFace: "Calibri", bold: true, color: C.navy,
    align: "left", valign: "top",
    margin: 0,
  });

  const tableData = [
    [
      { text: "Day", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Candidate Skill", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Validator", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
      { text: "Next-Day Action", options: { fill: { color: C.navy }, color: C.white, bold: true, align: "center" } },
    ],
    [
      { text: "1", options: { align: "center" } },
      { text: "git-push-with-auth-fallback", options: { align: "left" } },
      { text: "Accept", options: { fill: { color: "D1FAE5" }, color: C.accept, bold: true, align: "center" } },
      { text: "Add to Safety best pool", options: { align: "left" } },
    ],
    [
      { text: "2", options: { align: "center" } },
      { text: "git-push-with-auth-fallback", options: { align: "left" } },
      { text: "Accept", options: { fill: { color: "D1FAE5" }, color: C.accept, bold: true, align: "center" } },
      { text: "Keep updated best pool", options: { align: "left" } },
    ],
    [
      { text: "3", options: { align: "center" } },
      { text: "git-push-with-auth-fallback + git-clone-to-directory", options: { align: "left" } },
      { text: "Accept", options: { fill: { color: "D1FAE5" }, color: C.accept, bold: true, align: "center" } },
      { text: "Keep current best pool", options: { align: "left" } },
    ],
    [
      { text: "4", options: { align: "center" } },
      { text: "(none) — same-pool retest", options: { align: "left" } },
      { text: "Accept", options: { fill: { color: "D1FAE5" }, color: C.accept, bold: true, align: "center" } },
      { text: "Continue same best pool", options: { align: "left" } },
    ],
    [
      { text: "5", options: { align: "center" } },
      { text: "git-push-with-auth-fallback", options: { align: "left" } },
      { text: "Reject", options: { fill: { color: "FEE2E2" }, color: C.reject, bold: true, align: "center" } },
      { text: "Keep current best pool", options: { align: "left" } },
    ],
    [
      { text: "6", options: { align: "center" } },
